#!/usr/bin/env swift
//
// Builds Screvia.xcodeproj and copies the result to .build/Screvia.app.
//
//   swift scripts/BuildApp.swift [--no-open] [--sign <identity>]
//
// Without --sign it uses the first of these this Mac has: the project's
// self-signed "Screvia Code Signing" certificate (what releases are signed
// with), an "Apple Development" certificate, or an ad-hoc signature.
// Pass --sign - to force ad-hoc.
//
// Screvia.xcodeproj is generated by XcodeGen from project.yml and is
// gitignored, so this always regenerates it first. Everything else —
// bundling resources, embedding the LicenseList/KeyboardShortcuts plugin
// output, codesigning — is xcodebuild's job now; SwiftPM only builds the
// ScreviaKit library.

import Foundation

struct CommandError: LocalizedError {
    let command: String
    let status: Int32
    var errorDescription: String? { "\(command) exited with status \(status)" }
}

@discardableResult
func run(
    _ launchPath: String,
    _ arguments: [String],
    environment: [String: String]? = nil,
    captureOutput: Bool = false
) throws -> String {
    let process = Process()
    process.executableURL = URL(fileURLWithPath: launchPath)
    process.arguments = arguments
    if let environment {
        process.environment = ProcessInfo.processInfo.environment.merging(environment) { _, new in new }
    }

    let pipe = Pipe()
    if captureOutput {
        process.standardOutput = pipe
    }

    try process.run()
    // Read before waiting: a full pipe buffer would deadlock the child.
    let data = captureOutput ? pipe.fileHandleForReading.readDataToEndOfFile() : Data()
    process.waitUntilExit()

    guard process.terminationStatus == 0 else {
        throw CommandError(
            command: ([launchPath] + arguments).joined(separator: " "),
            status: process.terminationStatus
        )
    }

    return String(data: data, encoding: .utf8)?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
}

let fm = FileManager.default

// MARK: - Arguments

var shouldOpen = true
var signingIdentity: String?

var arguments = Array(CommandLine.arguments.dropFirst())
while let argument = arguments.first {
    arguments.removeFirst()
    switch argument {
    case "--no-open":
        shouldOpen = false
    case "--sign":
        guard let identity = arguments.first else {
            FileHandle.standardError.write(Data("--sign needs an identity\n".utf8))
            exit(2)
        }
        arguments.removeFirst()
        signingIdentity = identity
    default:
        FileHandle.standardError.write(Data("unknown argument: \(argument)\n".utf8))
        exit(2)
    }
}

// MARK: - Layout

let repoRoot = URL(fileURLWithPath: #filePath)
    .deletingLastPathComponent()
    .deletingLastPathComponent()
let buildRoot = repoRoot.appending(path: ".build")
let derivedDataDir = buildRoot.appending(path: "DerivedData")
let appDir = buildRoot.appending(path: "Screvia.app")

// LicenseList's build plugin looks for Xcode's SourcePackages layout, which
// a custom -derivedDataPath still provides — xcodebuild always writes it,
// unlike the SwiftPM CLI.
let buildEnvironment = ["PLL_SOURCE_PACKAGES_PATH": derivedDataDir.appending(path: "SourcePackages").path]

// MARK: - Signing

struct SigningError: LocalizedError {
    let identity: String
    var errorDescription: String? { "no team ID found in the certificate for \(identity)" }
}

/// Self-signed, so it needs no Apple Developer Program membership. Releases
/// are signed with it so that an update keeps the Screen Recording grant.
let projectSigningIdentity = "Screvia Code Signing"

// An ad-hoc signature's designated requirement is the binary's own hash, so
// macOS treats every rebuild as a new app and asks for Screen Recording
// again. A certificate-based requirement survives rebuilds. The project
// certificate comes first so local builds and releases count as the same
// app; machines with no certificate, such as CI, stay ad-hoc.
func defaultSigningIdentity() -> String {
    func identities(validOnly: Bool) -> String {
        (try? run(
            "/usr/bin/security",
            ["find-identity"] + (validOnly ? ["-v"] : []) + ["-p", "codesigning"],
            captureOutput: true
        )) ?? ""
    }
    // Self-signed certificates are never "valid" to `security`, so look for
    // the project one among all identities.
    if identities(validOnly: false).contains("\"\(projectSigningIdentity)\"") {
        return projectSigningIdentity
    }
    return identities(validOnly: true).contains("\"Apple Development:") ? "Apple Development" : "-"
}

/// Apple-issued certificates go through xcodebuild's own signing. Anything
/// else has no team, which xcodebuild requires, so it is applied afterwards.
func isAppleIssued(_ identity: String) -> Bool {
    identity.hasPrefix("Apple ") || identity.hasPrefix("Developer ID")
}

// Inside out: each nested bundle is sealed before the app that contains it.
// The entitlements xcodebuild added are dropped on purpose; the ad-hoc
// build carries none the app needs, and get-task-allow must not ship.
func resign(_ app: URL, with identity: String) throws {
    let nested = ["Contents/Frameworks", "Contents/Resources"].flatMap { directory in
        (try? fm.contentsOfDirectory(
            at: app.appending(path: directory),
            includingPropertiesForKeys: nil
        )) ?? []
    }.filter { ["bundle", "framework", "dylib"].contains($0.pathExtension) }

    for item in nested + [app] {
        try run(
            "/usr/bin/codesign",
            ["--force", "--options", "runtime", "--timestamp=none", "--sign", identity, item.path]
        )
    }
}

// xcodebuild will not sign with a certificate unless it also knows the team.
// That is the certificate subject's OU, not the ID in the certificate's name.
func teamID(for identity: String) throws -> String {
    let pem = try run(
        "/usr/bin/security",
        ["find-certificate", "-c", identity, "-p"],
        captureOutput: true
    )
    let pemURL = fm.temporaryDirectory.appending(path: "screvia-signing-\(UUID().uuidString).pem")
    try Data(pem.utf8).write(to: pemURL)
    defer { try? fm.removeItem(at: pemURL) }

    // LibreSSL prints "subject= /UID=…/CN=…/OU=<team>/O=…/C=US".
    let subject = try run(
        "/usr/bin/openssl",
        ["x509", "-in", pemURL.path, "-noout", "-subject"],
        captureOutput: true
    )
    guard let field = subject.split(separator: "/").first(where: { $0.hasPrefix("OU=") }) else {
        throw SigningError(identity: identity)
    }
    return String(field.dropFirst("OU=".count))
}

do {
    // Resolved through PATH: XcodeGen may come from Homebrew or Nix.
    try run("/usr/bin/env", ["xcodegen", "generate"], environment: buildEnvironment)

    let identity = signingIdentity ?? defaultSigningIdentity()
    var signingSettings = ["CODE_SIGN_IDENTITY=-"]
    if isAppleIssued(identity) {
        signingSettings = [
            "CODE_SIGN_IDENTITY=\(identity)",
            "DEVELOPMENT_TEAM=\(try teamID(for: identity))"
        ]
    }
    print("Signing with \(identity == "-" ? "an ad-hoc signature" : identity)")

    // An incremental build after xcodebuild's signer changes re-signs the
    // nested resource bundles without resealing the app around them. Start
    // the products over whenever the signer differs from the last build.
    let productsDir = derivedDataDir.appending(path: "Build")
    let signerMarker = derivedDataDir.appending(path: "xcodebuild-signer")
    let signer = signingSettings.joined(separator: " ")
    if (try? String(contentsOf: signerMarker, encoding: .utf8)) != signer {
        try? fm.removeItem(at: productsDir)
    }

    try run(
        "/usr/bin/xcodebuild",
        [
            "-project", "Screvia.xcodeproj",
            "-scheme", "Screvia",
            "-configuration", "Release",
            "-derivedDataPath", derivedDataDir.path,
            "-skipPackagePluginValidation"
        ] + signingSettings + ["build"],
        environment: buildEnvironment
    )
    try Data(signer.utf8).write(to: signerMarker)

    let builtApp = productsDir.appending(path: "Products/Release/Screvia.app")
    if fm.fileExists(atPath: appDir.path) {
        try fm.removeItem(at: appDir)
    }
    try run("/usr/bin/ditto", [builtApp.path, appDir.path])

    // Re-signing the copy rather than the build product keeps DerivedData
    // ad-hoc, so incremental builds never mix two signers.
    if identity != "-" && !isAppleIssued(identity) {
        try resign(appDir, with: identity)
    }

    // After a change of signing identity, an incremental build can re-sign
    // the nested resource bundle without resealing the app around it. The
    // result launches, but macOS no longer trusts it as the same app.
    do {
        try run("/usr/bin/codesign", ["--verify", "--deep", "--strict", appDir.path])
    } catch {
        FileHandle.standardError.write(Data("""
            The signature is broken, usually after switching --sign. \
            Remove \(derivedDataDir.appending(path: "Build").path) and build again.\n
            """.utf8))
        throw error
    }

    print("Built \(appDir.path)")

    if shouldOpen {
        try run("/usr/bin/open", [appDir.path])
    }
} catch {
    FileHandle.standardError.write(Data("error: \(error.localizedDescription)\n".utf8))
    exit(1)
}
